18	function get(port, path) {
19	  return new Promise((resolve, reject) => {
20	    http.get({ host: '127.0.0.1', port, path }, (res) => {
21	      const chunks = [];
22	      res.on('data', (chunk) => chunks.push(chunk));
23	      res.on('end', () => resolve({ status: res.statusCode, body: Buffer.concat(chunks) }));
24	    }).on('error', reject);
25	  });
26	}
