28	function request(port, method, path, body) {
29	  return new Promise((resolve, reject) => {
30	    const req = http.request({ host: '127.0.0.1', port, path, method }, (res) => {
31	      const chunks = [];
32	      res.on('data', (chunk) => chunks.push(chunk));
33	      res.on('end', () => resolve({ status: res.statusCode, body: Buffer.concat(chunks) }));
