  const res = await get(port, '/blobs');
  assert.equal(res.status, 200);
  const parsed = JSON.parse(res.body.toString());
  const keys = parsed.map((b) => b.key).sort();
  assert.deepEqual(keys, ['docs/readme.txt', 'top.txt']);
});

