  const dataDir = tempDataDir();
  const server = createServer({ dataDir });
  const port = await listen(server);
  t.after(() => server.close());

  // A single path segment this long is rejected by the filesystem
  // (ENAMETOOLONG) even though it passes all of resolveBlobPath's structural
  // checks (no traversal, no NUL, valid UTF-8). This stands in for the wider
  // class of keys that pass structural validation but fail at the actual
  // write/rename step for OS-level reasons - the fix must catch that class
  // generically, not this specific error code.
  const key = 'a'.repeat(300);
  const res = await request(port, 'PUT', `/blobs/${key}`, Buffer.from('x'));

  assert.equal(res.status, 400);
  assert.deepEqual(fs.readdirSync(dataDir), []);

