test('PUT /blobs/{key} with unusual decoded bytes (C1 control, supplementary plane, high Latin-1) never returns 500', async (t) => {
  const dataDir = tempDataDir();
  const server = createServer({ dataDir });
  const port = await listen(server);
  t.after(() => server.close());

  // The reported symptom: key decodes (via percent-encoding) to bytes that
  // are structurally valid (well-formed UTF-8, no traversal/NUL/surrogate
  // issues) but historically triggered an uncaught OS-level error during the
  // write itself. The contract allows only 201 or 400 here - never 500 -
  // regardless of whether this particular environment's filesystem happens
  // to accept the resulting name.
  const res = await request(port, 'PUT', '/blobs/e1%C2%8E%C2%B6%F3%9C%B8%A0', Buffer.from('x'));

  assert.notEqual(res.status, 500);
  assert.ok([201, 400].includes(res.status), `expected 201 or 400, got ${res.status}`);

  const health = await get(port, '/healthz');
  assert.equal(health.status, 200);
});

test('PUT /blobs/{key} still returns 201 for ordinary flat and nested keys after the write-failure handling', async (t) => {
  const dataDir = tempDataDir();
  const server = createServer({ dataDir });
  const port = await listen(server);
  t.after(() => server.close());

  const flat = await request(port, 'PUT', '/blobs/plain.txt', Buffer.from('flat'));
  assert.equal(flat.status, 201);

  const nested = await request(port, 'PUT', '/blobs/a/b/c.txt', Buffer.from('nested'));
  assert.equal(nested.status, 201);

  assert.deepEqual(fs.readFileSync(path.join(dataDir, 'plain.txt')), Buffer.from('flat'));
  assert.deepEqual(fs.readFileSync(path.join(dataDir, 'a', 'b', 'c.txt')), Buffer.from('nested'));
});

test('GET /blobs reflects overwrites (one entry per key, latest content)', async (t) => {
  const dataDir = tempDataDir();
  const server = createServer({ dataDir });
  const port = await listen(server);
  t.after(() => server.close());

  await request(port, 'PUT', '/blobs/a.txt', Buffer.from('first'));
  const second = Buffer.from('second, longer content');
  await request(port, 'PUT', '/blobs/a.txt', second);

  const res = await get(port, '/blobs');
