test('GET /blobs/{key} with unusual decoded bytes (C1 control, supplementary plane, high Latin-1) never returns 500', async (t) => {
  const dataDir = tempDataDir();
  const server = createServer({ dataDir });
  const port = await listen(server);
  t.after(() => server.close());

  // Same class of key as the PUT write-failure case: structurally valid
  // (well-formed UTF-8, no traversal/NUL/surrogate issues) but historically
  // able to trigger an uncaught OS-level error during stat/read. The
  // contract allows only 200, 404 or 400 here - never 500 - and since
  // nothing was ever stored under this key, 404 is the expected outcome.
  const res = await get(port, '/blobs/e1%C2%8E%C2%B6%F3%9C%B8%A0');

  assert.notEqual(res.status, 500);
  assert.ok([200, 404, 400].includes(res.status), `expected 200, 404 or 400, got ${res.status}`);

  const health = await get(port, '/healthz');
  assert.equal(health.status, 200);
});

test('GET /blobs/{key} with an unrepresentable long key never returns 500', async (t) => {
  const dataDir = tempDataDir();
  const server = createServer({ dataDir });
  const port = await listen(server);
  t.after(() => server.close());

  // A single path segment this long is rejected by the filesystem
  // (ENAMETOOLONG) even though it passes all of resolveBlobPath's structural
  // checks. Stands in for the wider class of keys that pass structural
  // validation but fail at the actual stat/read step for OS-level reasons.
  const key = 'a'.repeat(300);
  const res = await get(port, `/blobs/${key}`);

  assert.notEqual(res.status, 500);
  assert.ok([200, 404, 400].includes(res.status), `expected 200, 404 or 400, got ${res.status}`);

  const health = await get(port, '/healthz');
  assert.equal(health.status, 200);
});

test('GET /blobs/{key} still returns 200 for ordinary flat and nested keys after the read-failure handling', async (t) => {
  const dataDir = tempDataDir();
  const server = createServer({ dataDir });
  const port = await listen(server);
  t.after(() => server.close());

  await request(port, 'PUT', '/blobs/plain.txt', Buffer.from('flat'));
  await request(port, 'PUT', '/blobs/a/b/c.txt', Buffer.from('nested'));

  const flat = await get(port, '/blobs/plain.txt');
  assert.equal(flat.status, 200);
  assert.deepEqual(flat.body, Buffer.from('flat'));

  const nested = await get(port, '/blobs/a/b/c.txt');
  assert.equal(nested.status, 200);
  assert.deepEqual(nested.body, Buffer.from('nested'));
});

test('GET /blobs/{key} still returns 200 for a legitimate key with an unusual but valid substring', async (t) => {
  const dataDir = tempDataDir();
  const server = createServer({ dataDir });
  const port = await listen(server);
  t.after(() => server.close());

  // Combining diacritics and non-BMP characters are legal in a filename on
  // most real filesystems - only the pathological cases above should ever
  // be turned into a 404/400 substitute for 500.
  const key = 'näive-\u{1F600}.txt';
  const content = Buffer.from('valid unicode key');
  const putRes = await request(port, 'PUT', `/blobs/${encodeURIComponent(key)}`, content);
  assert.equal(putRes.status, 201);

